#[test]
fn apexomni_hosted_rest_uses_how_without_rewriting_signed_origins() {
    use safe_cex_native::{HttpRouteMode, resolve::route_bases};
    for (testnet, base) in [
        (false, "https://omni.apex.exchange/api"),
        (true, "https://testnet.omni.apex.exchange/api"),
    ] {
        let inputs = account_transport(
            "apexomni",
            &AccountTransport {
                testnet: Some(testnet),
                ..Default::default()
            },
        )
        .unwrap();
        assert_eq!(inputs.tealstreet_proxy, Some(true));
        assert_eq!(inputs.tealstreet_tunnel, Some(true));
        let plan = resolve_routing_plan("apexomni", &inputs, base, Provider::Tealstreet).unwrap();
        assert_eq!(plan.http.mode, HttpRouteMode::How);
        assert_eq!(
            plan.http.tunnel_url.as_ref(),
            Some(&route_bases().unwrap().tunnel["sg"])
        );
        assert!(plan.http.prefix.is_empty());
        assert!(
            !plan.http.authorize,
            "proxy token authenticates HOW, not the venue request"
        );
        assert!(plan.http.header_aliases.is_empty());
        for path in ["/v3/account", "/v3/account-balance", "/v3/open-orders"] {
            let url = reqwest::Url::parse(&format!("{base}{path}")).unwrap();
            assert_eq!(url.path(), format!("/api{path}"));
        }
        if testnet {
            assert!(
                plan.ws.private.host.is_none(),
                "testnet retains its native QA socket"
            );
        } else {
            let relay = reqwest::Url::parse(plan.ws.private.host.as_ref().unwrap()).unwrap();
            assert_eq!(
                relay
                    .query_pairs()
                    .find(|(key, _)| key == "ts-relay")
                    .unwrap()
                    .1,
                "wss://quote.omni.apex.exchange/realtime_private?v=2"
            );
        }
        assert!(plan.ws.private.fallback.is_none());
    }
}

#[test]
fn woo_private_relay_keeps_the_application_id_for_proxy_and_tunnel_accounts() {
    assert_eq!(
        safe_cex_native::resolve::rest_base_url("woo", false).unwrap(),
        "https://api.woox.io"
    );
    for flags in [
        serde_json::json!({"tealstreetProxy": true}),
        serde_json::json!({"tealstreetTunnel": true}),
    ] {
        let mut options = flags;
        options["applicationId"] = "application-123".into();
        options["hasKey"] = true.into();
        let inputs: RoutingInputs =
            serde_json::from_value(options).expect("public application metadata");
        let plan =
            resolve_routing_plan("woo", &inputs, "https://api.woox.io", Provider::Tealstreet)
                .unwrap();
        let host = plan
            .ws
            .private
            .host
            .expect("private socket must use the fleet relay");
        let url = reqwest::Url::parse(&host).unwrap();
        assert_eq!(
            url.query_pairs()
                .find(|(key, _)| key == "ts-relay")
                .unwrap()
                .1,
            "wss://wss.woox.io/v2/ws/private/stream/application-123"
        );
        assert!(plan.ws.private.fallback.is_none());
        assert!(plan.ws.public.host.is_none());
    }
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct Case {
    exchange: String,
    #[serde(rename = "baseURL")]
    base_url: String,
    account: Option<AccountTransport>,
    provider: Provider,
    options: serde_json::Value,
    plan: Option<serde_json::Value>,
    error: Option<String>,
}

/// The fields the native host applies, so absent-vs-default never differs.
fn applied(plan: serde_json::Value) -> serde_json::Value {
    let plan: RoutingPlan = serde_json::from_value(plan).expect("TS plan decodes");
    serde_json::to_value(plan).unwrap()
}

#[test]
fn every_case_matches_the_typescript_resolver() {
    let cases: Vec<Case> =
        serde_json::from_str(include_str!("fixtures/routing-port-plans.json")).unwrap();
    assert!(cases.len() > 400);
    for case in cases {
        let label = format!("{} {:?} {}", case.exchange, case.provider, case.options);
        let inputs: RoutingInputs = serde_json::from_value(case.options.clone()).unwrap();
        if let Some(account) = &case.account {
            let derived = account_transport(&case.exchange, account).unwrap();
            assert_eq!(
                derived.tealstreet_proxy, inputs.tealstreet_proxy,
                "proxy {label}"
            );
            assert_eq!(
                derived.tealstreet_tunnel, inputs.tealstreet_tunnel,
                "tunnel {label}"
            );
            assert_eq!(derived.proxy_region, inputs.proxy_region, "region {label}");
            assert_eq!(
                derived.tealstreet_ws_route, inputs.tealstreet_ws_route,
                "wsRoute {label}"
            );
        }
        let result = resolve_routing_plan(&case.exchange, &inputs, &case.base_url, case.provider);
        match (result, case.plan, case.error) {
            (Ok(plan), Some(expected), None) => {
                assert_eq!(
                    serde_json::to_value(plan).unwrap(),
                    applied(expected),
                    "{label}"
                )
            }
            (Err(error), None, Some(expected)) => {
                assert_eq!(error.to_string(), expected, "{label}")
            }
            (result, plan, error) => panic!("{label}: {result:?} vs plan {plan:?} error {error:?}"),
        }
    }
}

/// Every route that attaches the account's proxy token targets a table host.
#[test]
fn authorized_routes_only_ever_name_table_hosts() {
    let table: serde_json::Value =
        serde_json::from_str(include_str!("../src/routing/table.json")).unwrap();
    let hosts = &table["hosts"];
    let mut allowed: Vec<&str> = hosts["privateProxy"]
        .as_object()
        .unwrap()
        .values()
        .map(|v| v.as_str().unwrap())
        .collect();
    allowed.push(hosts["publicCorsProxy"].as_str().unwrap());
    let cases: Vec<Case> =
        serde_json::from_str(include_str!("fixtures/routing-port-plans.json")).unwrap();
    let mut authorized = 0;
    for case in cases.iter().filter(|c| c.provider == Provider::Tealstreet) {
        let inputs: RoutingInputs = serde_json::from_value(case.options.clone()).unwrap();
        let Ok(plan) = resolve_routing_plan(&case.exchange, &inputs, &case.base_url, case.provider)
        else {
            continue;
        };
        for route in [
            Some(&plan.http),
            plan.public_http.as_ref(),
            plan.public_cors_http.as_ref(),
        ]
        .into_iter()
        .flatten()
        .filter(|route| route.authorize)
        {
            authorized += 1;
            assert!(
                allowed.contains(&route.prefix.as_str()),
                "{} {}",
                case.exchange,
                route.prefix
            );
        }
    }
    assert!(authorized > 50);
}

#[test]
fn an_override_proxy_url_input_refuses() {
    let smuggled = serde_json::json!({"tealstreetProxy": true, "hasKey": true, "overrideProxyUrl": "https://evil.invalid"});
    assert!(serde_json::from_value::<RoutingInputs>(smuggled).is_err());
}

