#[test]
fn every_core_venue_base_url_pair_is_pinned_and_resolves() {
    use safe_cex_native::resolve::rest_base_url;
    for (venue, mainnet, testnet) in BASE_URLS {
        assert_eq!(rest_base_url(venue, false).ok(), Some(*mainnet), "{venue}");
        assert_eq!(rest_base_url(venue, true).ok(), *testnet, "{venue} testnet");
        for (is_testnet, base) in [(false, Some(*mainnet)), (true, *testnet)] {
            let Some(base) = base else { continue };
            let account = AccountTransport {
                tealstreet_proxy: Some(true),
                testnet: Some(is_testnet),
                ..Default::default()
            };
            let inputs = account_transport(venue, &account).unwrap();
            resolve_routing_plan(venue, &inputs, base, Provider::Tealstreet).unwrap();
        }
    }
    assert!(rest_base_url("hyrotrader", false).is_err());
}

#[test]
fn mexc_mainnet_uses_the_existing_proxy_for_every_saved_proxy_preference() {
    let base = safe_cex_native::resolve::rest_base_url("mexc", false).unwrap();
    let table: serde_json::Value =
        serde_json::from_str(include_str!("../src/routing/table.json")).unwrap();
    let expected = table["hosts"]["privateProxy"]["jp"].as_str().unwrap();
    assert!(!expected.is_empty());
    for saved_proxy in [None, Some(false), Some(true)] {
        for region in [None, Some("JA"), Some("SG")] {
            let account = AccountTransport {
                tealstreet_proxy: saved_proxy,
                proxy_region: region.map(str::to_owned),
                ..Default::default()
            };
            let inputs = account_transport("mexc", &account).unwrap();
            assert_eq!(inputs.tealstreet_proxy, Some(true));
            for public_only in [false, true] {
                let inputs = RoutingInputs {
                    public_data_only: Some(public_only),
                    has_key: !public_only,
                    ..inputs.clone()
                };
                let plan =
                    resolve_routing_plan("mexc", &inputs, base, Provider::Tealstreet).unwrap();
                assert_eq!(plan.http.mode, HttpRouteMode::Direct);
                assert_eq!(plan.http.prefix, expected);
                assert_eq!(plan.http.authorization_header, "Tealstreet-Authorization");
                assert!(plan.http.tunnel_url.is_none());
                assert!(plan.http.header_aliases.is_empty());
                assert!(plan.ws.public.host.is_none());
                assert!(plan.ws.private.host.is_none());
            }
        }
    }
}

#[test]
fn mexc_saved_tunnel_flags_keep_private_and_public_rest_on_the_japan_proxy() {
    let base = safe_cex_native::resolve::rest_base_url("mexc", false).unwrap();
    let table: serde_json::Value =
        serde_json::from_str(include_str!("../src/routing/table.json")).unwrap();
    let expected = table["hosts"]["privateProxy"]["jp"].as_str().unwrap();
    assert!(!expected.is_empty());
    for saved_tunnel in [None, Some(false), Some(true)] {
        let account = AccountTransport {
            tealstreet_proxy: Some(false),
            tealstreet_tunnel: saved_tunnel,
            ..Default::default()
        };
        let inputs = account_transport("mexc", &account).unwrap();
        for public_only in [false, true] {
            let inputs = RoutingInputs {
                public_data_only: Some(public_only),
                has_key: !public_only,
                ..inputs.clone()
            };
            let plan = resolve_routing_plan("mexc", &inputs, base, Provider::Tealstreet).unwrap();
            assert_eq!(plan.http.prefix, expected, "saved tunnel {saved_tunnel:?}");
            assert_eq!(plan.http.mode, HttpRouteMode::Direct);
            assert!(plan.http.tunnel_url.is_none());
            assert!(plan.ws.public.host.is_none());
            assert!(plan.ws.private.host.is_none());
        }
    }
}

